import {compoundSeries,bondPrice,tradeCosts} from './calculations.js';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,key,value,min,max,step=1)=>`<label class="field"><span>${label}</span><input type="number" data-value="${key}" value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${label}"></label>`;
const slider=(label,key,value,min,max,step=1,suffix='')=>`<label class="range-field"><span>${label}<strong>${value}${suffix}</strong></span><input type="range" data-value="${key}" value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${label}"><small>${min}${suffix}<span>${max}${suffix}</span></small></label>`;
function growthChart(rows,money){const W=640,H=230,left=60,bottom=195,top=20,right=620,max=Math.max(...rows.map(r=>r.compound),...rows.map(r=>r.simple),1);const x=r=>left+(right-left)*r.year/rows.at(-1).year,y=v=>bottom-(bottom-top)*v/max;const path=key=>rows.map((r,i)=>`${i?'L':'M'}${x(r).toFixed(2)},${y(r[key]).toFixed(2)}`).join(' ');return `<figure class="growth-chart"><svg role="img" aria-labelledby="growth-title growth-desc" viewBox="0 0 ${W} ${H}"><title id="growth-title">Hypothetical balance over time</title><desc id="growth-desc">At year ${rows.at(-1).year}: contributions ${money(rows.at(-1).contributions)}, simple interest ${money(rows.at(-1).simple)}, compound interest ${money(rows.at(-1).compound)}. Exact yearly values follow in the table.</desc>${[0,.5,1].map(v=>`<line x1="${left}" y1="${y(max*v)}" x2="${right}" y2="${y(max*v)}" stroke="#e7e2ed"/><text x="${left-8}" y="${y(max*v)+4}" text-anchor="end" font-size="10" fill="#766d83">${new Intl.NumberFormat('en-CA',{notation:'compact',style:'currency',currency:'CAD',maximumFractionDigits:1}).format(max*v)}</text>`).join('')}<path d="${path('contributions')}" fill="none" stroke="#a3a099" stroke-width="2" stroke-dasharray="5 4"/><path d="${path('simple')}" fill="none" stroke="#c98e65" stroke-width="2.5"/><path d="${path('compound')}" fill="none" stroke="#7860ae" stroke-width="3.5"/><text x="${left}" y="218" font-size="11" fill="#766d83">Start</text><text x="${right}" y="218" text-anchor="end" font-size="11" fill="#766d83">Year ${rows.at(-1).year}</text></svg><figcaption><span><i style="background:#7860ae"></i>Compound interest</span><span><i style="background:#c98e65"></i>Simple interest</span><span><i style="background:#a3a099"></i>Your contributions</span></figcaption></figure>`}
export const sampleFunds=[
{id:'A',name:'Maple 500 A',index:'S&P 500',currency:'CAD',hedge:'Unhedged',mer:.08,price:50,us:100,other:0},
{id:'B',name:'Maple 500 B',index:'S&P 500',currency:'CAD',hedge:'Unhedged',mer:.12,price:100,us:100,other:0},
{id:'C',name:'Maple 500 Hedged',index:'S&P 500',currency:'CAD',hedge:'CAD hedged',mer:.20,price:25,us:100,other:0},
{id:'D',name:'World Basket',index:'Fictional global equity index',currency:'CAD',hedge:'Unhedged',mer:.22,price:40,us:60,other:40}];
export function renderExtendedActivity(name,a,money){
 money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
if(name==='compound'){
 const principal=a.principal??1000,monthly=a.monthly??100,years=a.years??20,rate=a.rate??5,frequency=a.frequency??12,inflation=a.inflation??2;
 const rows=compoundSeries(principal,monthly,years,rate,frequency,inflation),last=rows.at(-1);
 return `<div class="activity"><div class="activity-head"><strong>The compounding playground</strong><span>Interest earns interest.</span></div><div class="activity-content"><div class="lab-prompt">Try this: set contributions to $0. Compare 5% over 10 years and 30 years. Then add $100 each month. What changes most?</div><div class="lab-controls"><div>${field('Starting money ($)','principal',principal,0,100000)}${field('Monthly contribution ($)','monthly',monthly,0,10000)}<label class="field"><span>Interest credited</span><select data-value="frequency" aria-label="Interest credited"><option value="12" ${frequency===12?'selected':''}>Monthly</option><option value="1" ${frequency===1?'selected':''}>Annually</option></select></label></div><div>${slider('Annual interest rate','rate',rate,0,15,.1,'%')}${slider('Years to grow','years',years,1,50,1)}${slider('Annual inflation','inflation',inflation,0,10,.1,'%')}</div></div>${growthChart(rows,money)}<div class="stats"><div class="stat">Your contributions<strong>${money(last.contributions)}</strong></div><div class="stat good">Compound balance<strong>${money(last.compound)}</strong><span>${money(last.compound-last.contributions)} in interest</span></div><div class="stat">Simple-interest balance<strong>${money(last.simple)}</strong></div></div><div class="lab-insight"><strong>${money(last.compound-last.simple)} extra from compounding</strong><p>With ${inflation}% annual inflation, the compound balance buys about what ${money(last.real)} buys today. This is purchasing power, not an additional fee.</p></div><details class="year-table"><summary>See the yearly numbers</summary><div class="table-scroll"><table><thead><tr><th>Year</th><th>Contributions</th><th>Simple interest balance</th><th>Compound balance</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${r.year}</th><td>${money(r.contributions)}</td><td>${money(r.simple)}</td><td>${money(r.compound)}</td></tr>`).join('')}</tbody></table></div></details><p class="fineprint">Hypothetical fixed nominal annual interest rate, not a product quote or forecast. Interest accrues each month on the balance; it is added monthly or at year-end. Contributions arrive at month-end. Simple interest accrues only on contributed money, without earning interest on past interest. No tax or fees. Inflation compounds annually. Market investments do not promise a fixed interest rate; their returns vary and can be negative.</p></div></div>`;
}
if(name==='bondrates'){
 const coupon=a.coupon??4,yieldRate=a.yield??4,years=a.years??5,face=1000,price=bondPrice(face,coupon,years,yieldRate);
 return `<div class="activity"><div class="activity-head"><strong>Old bond. New market rate.</strong><span>Face value: $1,000</span></div><div class="activity-content"><p class="lab-prompt">An existing bond keeps its promised coupon. If new bonds pay more, would you pay full price for this one?</p>${slider('Bond coupon rate','coupon',coupon,0,10,.1,'%')}${slider('Market yield required by buyers','yield',yieldRate,0,12,.1,'%')}${slider('Years until maturity','years',years,1,20)}<div class="stats"><div class="stat">Annual coupon<strong>${money(face*coupon/100)}</strong></div><div class="stat ${price<face?'warn':'good'}">Model bond price<strong>${money(price)}</strong></div><div class="stat">Face value at maturity<strong>$1,000</strong></div></div><div class="lab-insight"><strong>${yieldRate>coupon?'Higher market yield → lower price.':yieldRate<coupon?'Lower market yield → higher price.':'Coupon equals market yield → price equals face value.'}</strong><p>The fixed coupon is ${money(face*coupon/100)} per year. The price changes so its cash flows match the yield buyers now require. Try a longer term to see more sensitivity.</p></div><p class="fineprint">Simplified annual-coupon bond: price is the present value of all coupons and the $1,000 maturity payment, discounted at your selected annual yield. Assumes full timely payment, unchanged credit risk, no accrued interest, fees or taxes. Many Canadian bonds pay semi-annually. Bond funds hold changing portfolios and do not work exactly like one bond held to maturity.</p></div></div>`;
}
if(name==='etfcompare'){
 const A=sampleFunds.find(f=>f.id===(a.fundA??'A'))??sampleFunds[0],B=sampleFunds.find(f=>f.id===(a.fundB??'B'))??sampleFunds[1],weight=a.weight??50,us=(A.us*weight+B.us*(100-weight))/100,mer=(A.mer*weight+B.mer*(100-weight))/100;
 const select=(label,key,value)=>`<label class="field"><span>${label}</span><select data-choice="${key}" aria-label="${label}">${sampleFunds.map(f=>`<option value="${f.id}" ${value===f.id?'selected':''}>${f.name}</option>`).join('')}</select></label>`;
 return `<div class="activity"><div class="activity-head"><strong>Different labels. Same basket?</strong><span>Fictional funds, invented fees.</span></div><div class="activity-content"><p class="lab-prompt">Start with A + B. Then swap B for the hedged fund, or the global fund. Which change adds different underlying exposure?</p>${select('First sample fund','fundA',A.id)}${select('Second sample fund','fundB',B.id)}${slider('Allocation to first fund','weight',weight,0,100,5,'%')}<div class="table-scroll"><table class="comparison-table"><thead><tr><th>Look beneath the label</th><th>${A.name}</th><th>${B.name}</th></tr></thead><tbody>${[['Tracks',A.index,B.index],['Trading currency',A.currency,B.currency],['Currency policy',A.hedge,B.hedge],['Sample annual MER',A.mer+'%',B.mer+'%'],['Sample unit price',money(A.price),money(B.price)],['MER on $10,000 / year',money(A.mer*100),money(B.mer*100)]].map(r=>`<tr>${r.map((v,i)=>i===0?'<th>'+safe(v)+'</th>':'<td>'+safe(v)+'</td>').join('')}</tr>`).join('')}</tbody></table></div><div class="stats"><div class="stat">U.S. large-company exposure<strong>${Math.round(us)}%</strong></div><div class="stat">Other equity exposure<strong>${Math.round(100-us)}%</strong></div><div class="stat">Blended example MER<strong>${mer.toFixed(3)}%</strong></div></div><div class="lab-insight"><strong>${A.index===B.index?'Buying two wrappers does not add a new stock market.':'The sample global fund adds other markets, but still overlaps U.S. stocks.'}</strong><p>${A.hedge!==B.hedge?'Hedging changes currency exposure, not the underlying U.S. company basket. ':''}A lower unit price is not automatically a cheaper valuation or lower fee. Compare equal dollar investments, holdings, total costs, currency policy, and tracking.</p></div><p class="fineprint">All funds, prices, fees and the 60/40 global split are invented for teaching. Same-index funds generally have substantial overlap; implementation may vary. This model treats their underlying stock exposure as identical. Hedging does not remove stock-market risk. Real global indexes can include different company sizes and regions.</p></div></div>`;
}
if(name==='costs'){
 const product=a.product??'etf';const copy={etf:{title:'ETFs & mutual funds',text:'Fund-level costs: management fee plus operating expenses and applicable taxes form the MER. TER (trading expense ratio) is separate. Fund costs reduce the fund’s value; you usually do not see a separate MER invoice. ETFs can also involve brokerage commission, bid–ask spread and currency conversion. Mutual fund purchase, redemption and account charges depend on the fund and platform.',fee:.2},stock:{title:'Individual stocks',text:'There is no fund MER for directly holding a company’s stock. Your broker may charge trading commission, currency conversion, account or advisory fees. The bid–ask spread affects execution. A commission-free trade can still involve costs.',fee:0},bond:{title:'Individual bonds',text:'Dealer commission or a markup/markdown may be embedded in the quoted price. Bid–ask spreads and currency costs can apply. A bond fund adds fund expenses such as MER and TER. Coupon and yield are returns, not fee names.',fee:0},gic:{title:'Cash & GICs',text:'Check account charges, minimum balances, transfer charges and cashability. A GIC may have no separately billed purchase fee, while issuer/broker compensation is reflected in product pricing. Early access may be prohibited or reduce interest under the terms. A higher advertised rate can come with different conditions.',fee:0},crypto:{title:'Direct crypto',text:'A platform may charge trading fees, spreads, deposit/withdrawal charges and currency conversion. On-chain transfers may require network fees. Custody arrangements introduce additional risks and possible charges. A crypto ETF adds fund expenses; it does not remove crypto price risk.',fee:0}};const d=copy[product]??copy.etf,amount=a.amount??1000,commission=a.commission??5,spread=a.spread??.2,fx=a.fx??0,mer=a.mer??d.fee,c=tradeCosts(amount,commission,spread,fx,mer);
 return `<div class="activity"><div class="activity-head"><strong>Follow the costs</strong><span>Read the fee schedule, not just the headline.</span></div><div class="activity-content"><div class="segments">${Object.entries(copy).map(([k,v])=>`<button data-product="${k}" class="${product===k?'active':''}">${v.title}</button>`).join('')}</div><div class="lab-insight"><h3>${d.title}</h3><p>${d.text}</p></div><h3 style="font-size:15px;margin-top:23px">A simplified cost microscope</h3>${field('Trade amount ($)','amount',amount,0,100000)}${field('Commission on this purchase ($)','commission',commission,0,1000,.01)}${field('Full bid–ask spread (%)','spread',spread,0,10,.01)}${field('Currency conversion on purchase (%)','fx',fx,0,10,.1)}${field('Annual fund MER, if applicable (%)','mer',mer,0,10,.01)}<div class="cost-breakdown"><p><span>Commission</span><strong>${money(c.commission)}</strong></p><p><span>Estimated half-spread versus midpoint</span><strong>${money(c.spread)}</strong></p><p><span>Currency conversion</span><strong>${money(c.fx)}</strong></p><p class="cost-total"><span>Illustrative entry friction</span><strong>${money(c.entry)}</strong></p><p><span>Separate annual fund cost on unchanged balance</span><strong>${money(c.annualFund)}</strong></p></div><p class="fineprint">All values are editable teaching assumptions, not platform/product quotes. Entry estimate = commission + half the full percentage spread × trade amount + FX percentage × trade amount; line items are applied independently. Annual MER estimate = unchanged holding value × MER. MER already includes the management fee: do not add it twice. TER, advisory costs, exits, tax, network fees and market moves are excluded. For direct assets use 0% MER. Not every listed charge applies to every product.</p></div></div>`;
}
return null;
}
